  "implementation": "def solve(case):
    import math
    matrix = case['matrix']
    if not matrix or not matrix[0]:
        raise ValueError('nonempty rectangular matrix required')
    n = len(matrix)
    m = len(matrix[0])
    for row in matrix:
        if len(row) != m:
            raise ValueError('matrix must be rectangular')
    df = [0] * m
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    idf = [math.log(1 + n / (1 + dfj)) for dfj in df]
    weighted = []
    for row in matrix:
        wrow = [row[j] * idf[j] for j in range(m)]
        weighted.append(wrow)
    row_degree = [sum(wrow) for wrow in weighted]
    idf_rounded = [round(x, 6) for x in idf]
    row_degree_rounded = [round(x, 6) for x in row_degree]
    weighted_rounded = [[round(x, 6) for x in row] for row in weighted]
    return {
        'idf': idf_rounded,
        'row_degree': row_degree_rounded,
        'weighted_matrix': weighted_rounded
    }"
}
